1	import Link from "next/link";
2	import { requireArea } from "@/lib/rbac";
3	import { db } from "@/lib/db";
4	import { PageHeader, StatCard, StatusDot, Badge, timeAgo } from "@/components/ui/primitives";
5	
6	export const dynamic = "force-dynamic";
7	
8	const PRIORITY_ORDER: Record<string, number> = { URGENT: 0, HIGH: 1, NORMAL: 2, LOW: 3 };
9	const PRIORITY_TONE: Record<string, "red" | "amber" | "brand" | "slate"> = {
10	  URGENT: "red",
11	  HIGH: "amber",
12	  NORMAL: "brand",
13	  LOW: "slate",
14	};
15	
16	export default async function AdminSupport() {
17	  await requireArea("support");
18	
19	  const since7d = new Date(Date.now() - 7 * 86400_000);
20	
21	  const [tickets, closed7d, statusCounts] = await Promise.all([
22	    db.ticket.findMany({
23	      include: {
24	        user: { select: { id: true, email: true, name: true } },
25	        _count: { select: { messages: true } },
26	      },
27	      orderBy: { updatedAt: "desc" },
28	      take: 200,
29	    }),
30	    db.ticket.count({ where: { status: "CLOSED", updatedAt: { gte: since7d } } }),
31	    db.ticket.groupBy({ by: ["status"], _count: true }),
32	  ]);
33	
34	  const countOf = (s: string) => statusCounts.find((c) => c.status === s)?._count ?? 0;
35	  const open = countOf("OPEN");
36	  const awaitingStaff = open + countOf("CUSTOMER_REPLY");
37	  const answered = countOf("ANSWERED");
38	
39	  const sorted = [...tickets].sort((a, b) => {
40	    const aClosed = a.status === "CLOSED" ? 1 : 0;
41	    const bClosed = b.status === "CLOSED" ? 1 : 0;
42	    if (aClosed !== bClosed) return aClosed - bClosed;
43	    const p = PRIORITY_ORDER[a.priority] - PRIORITY_ORDER[b.priority];
44	    if (p !== 0) return p;
45	    return b.updatedAt.getTime() - a.updatedAt.getTime();
46	  });
47	
48	  return (
49	    <div className="space-y-6">
50	      <PageHeader title="Support desk" sub="Customer tickets, sorted by urgency — urgent first, closed sink." />
51	
52	      <div className="grid grid-cols-2 gap-4 xl:grid-cols-4">
53	        <StatCard label="Open" value={String(open)} delta={open > 0 ? "unanswered" : "clear"} deltaGood={open === 0} />
54	        <StatCard
55	          label="Awaiting staff"
56	          value={String(awaitingStaff)}
57	          delta="open + customer replies"
58	          deltaGood={awaitingStaff === 0}
59	        />
60	        <StatCard label="Answered" value={String(answered)} delta="waiting on customer" />
61	        <StatCard label="Closed · 7d" value={String(closed7d)} delta="resolved this week" />
62	      </div>
63	
64	      <div className="card overflow-x-auto p-0">
65	        <table className="table-shell">
66	          <thead>
67	            <tr>
68	              <th>Subject</th>
69	              <th>Customer</th>
70	              <th>Priority</th>
71	              <th>Status</th>
72	              <th>Messages</th>
73	              <th className="text-right">Updated</th>
74	            </tr>
75	          </thead>
76	          <tbody>
77	            {sorted.length === 0 && (
78	              <tr>
79	                <td colSpan={6} className="py-10 text-center text-slate-500">
80	                  No tickets yet — the queue is empty.
81	                </td>
82	              </tr>
83	            )}
84	            {sorted.map((t) => (
85	              <tr key={t.id} className={t.status === "CLOSED" ? "opacity-60" : undefined}>
86	                <td>
87	                  <Link href={`/admin/support/${t.id}`} className="font-medium hover:text-brand-300">
88	                    {t.subject}
89	                  </Link>
90	                </td>
91	                <td>
92	                  <Link href={`/admin/users/${t.user.id}`} className="text-slate-300 hover:text-brand-300">
93	                    {t.user.email}
94	                  </Link>
95	                </td>
96	                <td>
97	                  <Badge tone={PRIORITY_TONE[t.priority] ?? "slate"}>{t.priority.toLowerCase()}</Badge>
98	                </td>
99	                <td>
100	                  <StatusDot status={t.status} />
101	                </td>
102	                <td>{t._count.messages}</td>
103	                <td className="text-right text-xs text-slate-400">{timeAgo(t.updatedAt)}</td>
104	              </tr>
105	            ))}
106	          </tbody>
107	        </table>
108	      </div>
109	    </div>
110	  );
111	}
