9	const KINDS = ["BUG", "FEATURE"] as const;
10	const STATUSES = ["NEW", "PLANNED", "IN_PROGRESS", "DONE", "DECLINED"] as const;
11	
12	const statusTone: Record<string, "slate" | "brand" | "amber" | "green" | "red"> = {
13	  NEW: "slate",
14	  PLANNED: "brand",
15	  IN_PROGRESS: "amber",
16	  DONE: "green",
17	  DECLINED: "red",
18	};
