20	function filterHref(kind: string | undefined, status: string | undefined): string {
21	  const p = new URLSearchParams();
22	  if (kind) p.set("kind", kind);
23	  if (status) p.set("status", status);
24	  const q = p.toString();
25	  return q ? `/admin/feedback?${q}` : "/admin/feedback";
26	}
