28	function Pill({
29	  active,
30	  href,
31	  children,
32	}: {
33	  active: boolean;
34	  href: string;
35	  children: React.ReactNode;
36	}) {
37	  return (
38	    <Link
39	      href={href}
40	      className={
41	        active
42	          ? "rounded-full border border-brand-500/50 bg-brand-500/15 px-3 py-1 text-xs font-medium text-brand-200"
43	          : "rounded-full border border-white/10 bg-white/[0.03] px-3 py-1 text-xs font-medium text-slate-400 hover:text-slate-200"
44	      }
45	    >
46	      {children}
47	    </Link>
