72	                  <span className="text-xs text-slate-500">{cards.length}</span>
73	                </div>
74	                {colValue > 0 && <div className="mb-2 text-[11px] text-slate-500">{fmtMoney(colValue)}</div>}
75	                <div className="space-y-2">
76	                  {cards.map((p) => (
77	                    <div key={p.id} className="rounded-lg border border-white/[0.06] bg-white/[0.03] p-3">
78	                      <Link href={`/admin/agency/prospects/${p.id}`} className="font-medium text-white hover:underline">
79	                        {p.businessName}
80	                      </Link>
81	                      <div className="mt-0.5 text-xs text-slate-500">
82	                        {p.vertical || "—"} · {fmtMoney(p.dealValueCents)}
83	                      </div>
84	                      <div className="mt-1 text-[11px] text-slate-600">
85	                        {p._count.demos} demo{p._count.demos === 1 ? "" : "s"} · {p._count.activities} activit
86	                        {p._count.activities === 1 ? "y" : "ies"}
87	                      </div>
88	                      <div className="mt-2">
89	                        <StageMover id={p.id} stage={p.stage as DealStage} />
90	                      </div>
91	                    </div>
92	                  ))}
93	                  {cards.length === 0 && <p className="text-xs text-slate-600">—</p>}
94	                </div>
95	              </div>
96	            );
97	          })}
98	        </div>
99	      )}
100	    </div>
101	  );
102	}
